import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const args=new Map();for(let index=2;index<process.argv.length;++index){const name=process.argv[index];if(!name.startsWith('--')||index+1>=process.argv.length)throw new Error(`Invalid argument: ${name}`);args.set(name.slice(2),process.argv[++index]);}
const required=name=>{const value=args.get(name);if(!value)throw new Error(`Missing --${name}`);return resolve(value);};
const inputs={x64:{native:required('x64-native'),browser:required('x64-browser')},ARM64:{native:required('arm64-native'),browser:required('arm64-browser')}};const output=required('output');
const read=async path=>JSON.parse((await readFile(path,'utf8')).replace(/^\uFEFF/,''));const mean=values=>values.reduce((sum,value)=>sum+value,0)/values.length;
const stats=values=>{const average=mean(values);const variance=mean(values.map(value=>(value-average)**2));const sorted=[...values].sort((a,b)=>a-b);return{count:values.length,mean:average,median:sorted[Math.floor(sorted.length/2)],min:sorted[0],max:sorted.at(-1),standardDeviation:Math.sqrt(variance),coefficientOfVariationPercent:average?100*Math.sqrt(variance)/average:null};};
async function analyzeRun(root,run,warmupFrames,frames){const telemetry=await read(resolve(dirname(root),run.telemetry));const selected=telemetry.frames.filter(frame=>!frame.startup&&frame.detailed!==false&&frame.frame>=warmupFrames&&frame.frame<frames);if(selected.length!==frames-warmupFrames)throw new Error(`Steady frame mismatch: ${run.cell} r${run.repeat}`);const series=selected.map(frame=>{const scopes=Object.fromEntries(frame.scopes.map(scope=>[scope.name,scope.totalMs]));const wait=(scopes['gpu.gpu_wait']??0)+(scopes['webgpu.surface_acquire']??0);const present=scopes['gpu.present']??0;return{cpu:frame.cpuFrameMs,nonWait:Math.max(0,frame.cpuFrameMs-wait-present),wait,present,encode:scopes['gpu.encode']??0,submit:scopes['gpu.submit']??0,update:scopes['frame.update']??0,draw:scopes['frame.draw']??0,graph:frame.scopes.filter(scope=>scope.name.startsWith('render.pass.')).reduce((sum,scope)=>sum+scope.totalMs,0)};});const work=selected.map(frame=>({frame:frame.frame,counters:frame.counters.filter(counter=>/^(gpu\.(draws|indices|dispatch)|render\.pass\..*\.(draws|indices)|render\.pass\.count|compute\.)/.test(counter.name)).sort((a,b)=>a.name.localeCompare(b.name))}));return{cell:run.cell,repeat:run.repeat,adapterId:telemetry.adapterId,workHash:createHash('sha256').update(JSON.stringify(work)).digest('hex'),metrics:Object.fromEntries(Object.keys(series[0]).map(key=>[key,stats(series.map(frame=>frame[key]))]))};}
async function analyzeMachine(label,paths){const native=await read(paths.native);const browser=await read(paths.browser);for(const input of [native,browser])if(!input.passed||input.repetitions!==3||input.frames!==1800||input.warmupFrames!==300||input.width!==1920||input.height!==1080||input.postProcessMode!=='compute'||input.shaderFlow!=='wgsl')throw new Error(`${label} input contract mismatch`);if(native.machine!==browser.machine||native.architecture!==browser.architecture)throw new Error(`${label} host identity mismatch`);const runs=[];for(const run of native.runs)runs.push(await analyzeRun(paths.native,run,native.warmupFrames,native.frames));for(const run of browser.runs)runs.push(await analyzeRun(paths.browser,run,browser.warmupFrames,browser.frames));if(runs.length!==9)throw new Error(`${label} run count mismatch`);if(new Set(runs.map(run=>run.workHash)).size!==1)throw new Error(`${label} frame work differs across backends`);const cells=[];for(const cell of ['d3d12','webgpu','edge']){const group=runs.filter(run=>run.cell===cell);if(group.length!==3)throw new Error(`${label} ${cell} repetition mismatch`);const metric={};for(const name of Object.keys(group[0].metrics))metric[name]=stats(group.map(run=>run.metrics[name].mean));cells.push({cell,runs:group.length,metrics:metric});}const baseline=cells[0].metrics.nonWait.mean;for(const cell of cells){cell.nonWaitOverD3D12Ms=cell.metrics.nonWait.mean-baseline;cell.nonWaitOverD3D12Percent=baseline?100*(cell.metrics.nonWait.mean-baseline)/baseline:null;}return{label,machine:native.machine,architecture:native.architecture,nativeExecutableSha256:native.executableSha256,browserRuntimeIdentity:browser.runtimeIdentity,browserVersion:browser.cdpVersion?.Browser,scenario:{width:native.width,height:native.height,frames:native.frames,warmupFrames:native.warmupFrames,measuredFrames:native.frames-native.warmupFrames,postProcessMode:native.postProcessMode,shaderFlow:native.shaderFlow},workHash:runs[0].workHash,cells,runs};}
const result={schema:1,generatedUtc:new Date().toISOString(),metric:'Non-wait CPU wall time = cpuFrameMs - gpu.gpu_wait - webgpu.surface_acquire - gpu.present; identical to the retained Saturday analysis.',machines:[]};result.machines.push(await analyzeMachine('x64',inputs.x64));result.machines.push(await analyzeMachine('ARM64',inputs.ARM64));if(result.machines[0].browserRuntimeIdentity!==result.machines[1].browserRuntimeIdentity)throw new Error('Browser runtime identities differ');await writeFile(output,JSON.stringify(result,null,2)+'\n');console.log(`Cross-machine CPU overhead written: ${output}`);